function el(tag, props = {}, ...children) {
  const e = document.createElement(tag);
  Object.assign(e, props);
  e.append(...children);
  return e;
}

function haHost(panel) {
  const ws = msg => panel.hass.callWS(msg);
  let ui, panels = [], configs = [], currentConfig = null;
  const cards = {};

  const status = p => p.auth_failed ? ['bad', 'mit anderem HA gekoppelt: am Panel Debug-Screen → SW6 RESET']
    : p.mode === 'local' ? ['', 'lokal verwaltet'] : p.connected ? ['on', 'verbunden'] : ['', 'offline'];

  async function refresh() {
    [panels, configs] = await Promise.all([ws({type: 'smartbuttons/panels'}), ws({type: 'smartbuttons/configs'})]);
  }

  async function act(promise, okText) {
    try {
      const r = await promise;
      if (okText) ui.msg(typeof okText === 'function' ? okText(r) : okText, 'ok');
      return r;
    } catch (e) {
      ui.msg('Fehler: ' + (e.message || e.code || e), 'err');
      throw e;
    }
  }

  // ── Panels: name, configuration, mounting ──
  function renderPanels() {
    const rows = panels.map(p => {
      const [dotClass, text] = status(p);
      const name = el('input', {value: p.name});
      const rename = el('button', {textContent: 'Umbenennen', disabled: true});
      name.oninput = () => { rename.disabled = !name.value.trim() || name.value === p.name; };
      rename.onclick = async () => {
        await act(ws({type: 'smartbuttons/update_panel', entry_id: p.entry_id, name: name.value}),
                  r => `Umbenannt in ${r.name}, das Panel startet neu.`);
        await reload();
      };
      const config = el('select', {disabled: !p.config, title: p.config ? '' : 'Erst nach der ersten Verbindung'});
      for (const c of configs) config.append(el('option', {value: c.id, textContent: c.name, selected: c.id === p.config}));
      config.onchange = async () => {
        await act(ws({type: 'smartbuttons/update_panel', entry_id: p.entry_id, config_id: config.value}),
                  'Konfiguration zugewiesen, das Panel startet neu.');
        await reload();
      };
      const rot = el('input', {type: 'checkbox', checked: p.rotate_180, disabled: !p.config});
      rot.onchange = () => act(ws({type: 'smartbuttons/update_panel', entry_id: p.entry_id, rotate_180: rot.checked}),
                               'Einbaulage gesetzt, das Panel startet neu.');
      const locate = el('button', {textContent: 'Finden', disabled: !p.connected,
                                   title: 'Obere Reihe blinkt, eine Taste am Panel beendet'});
      locate.onclick = () => act(ws({type: 'smartbuttons/locate', entry_id: p.entry_id}),
                                 `${p.name} blinkt, eine Taste am Panel beendet.`);
      return el('tr', {},
        el('td', {className: 'name'}, el('div', {className: 'inline'}, name, rename),
           el('div', {className: 'state', textContent: `ID ${p.id}` + (p.host ? ` · ${p.host}` : '')})),
        el('td', {}, el('div', {className: 'inline'},
                        el('span', {}, el('span', {className: 'dot ' + dotClass}), el('span', {textContent: text})),
                        locate),
           el('div', {className: 'state', textContent: p.version || ''})),
        el('td', {}, config),
        el('td', {}, el('label', {className: 'check'}, rot, '180°')));
    });
    cards.panels.replaceChildren(
      el('h2', {textContent: 'Panels'}),
      panels.length
        ? el('table', {className: 'panels'},
            el('tr', {}, ...['Name', 'Status', 'Konfiguration', 'Einbaulage'].map(t => el('th', {textContent: t}))),
            ...rows)
        : el('p', {className: 'hint', textContent: 'Noch kein Panel: Einstellungen → Geräte & Dienste → SmartButtons.'}),
      el('p', {className: 'hint', textContent:
        'Neue Panels bringen ihre Belegung als eigene Konfiguration mit. Konfiguration oder Einbaulage ändern startet das Panel neu.'}));
  }

  // ── Configurations: pick, create, copy, rename, delete ──
  function renderConfigs() {
    const pick = el('select');
    for (const c of configs) pick.append(el('option', {value: c.id, textContent: c.name, selected: c.id === currentConfig}));
    pick.onchange = () => openConfig(pick.value);
    const cur = configs.find(c => c.id === currentConfig);
    const name = el('input', {value: cur ? cur.name : '', disabled: !cur});
    const rename = el('button', {textContent: 'Umbenennen', disabled: true});
    name.oninput = () => { rename.disabled = !name.value.trim() || !cur || name.value === cur.name; };
    rename.onclick = async () => {
      await act(ws({type: 'smartbuttons/save_config', config_id: currentConfig, name: name.value.trim()}), 'Umbenannt.');
      await reload();
    };
    const create = el('button', {textContent: 'Neu'});
    create.onclick = async () => {
      const r = await act(ws({type: 'smartbuttons/create_config', name: 'Neue Konfiguration'}));
      currentConfig = r.config_id;
      await reload();
    };
    const copy = el('button', {textContent: 'Kopieren', disabled: !cur});
    copy.onclick = async () => {
      const r = await act(ws({type: 'smartbuttons/create_config', name: `${cur.name} (Kopie)`, copy_from: currentConfig}));
      currentConfig = r.config_id;
      await reload();
    };
    const del = el('button', {textContent: 'Löschen', disabled: !cur || cur.panels.length > 0,
                              title: cur && cur.panels.length ? 'Wird noch von einem Panel benutzt' : ''});
    del.onclick = async () => {
      if (!confirm(`Konfiguration „${cur.name}“ löschen?`)) return;
      await act(ws({type: 'smartbuttons/delete_config', config_id: currentConfig}), 'Gelöscht.');
      currentConfig = null;
      await reload();
    };
    cards.configs.replaceChildren(
      el('h2', {textContent: 'Konfiguration bearbeiten'}),
      el('div', {className: 'inline'}, pick, create, copy, del),
      el('div', {className: 'inline', style: 'margin-top:8px'}, name, rename),
      el('p', {className: 'hint', textContent: cur
        ? (cur.panels.length ? `Benutzt von: ${cur.panels.join(', ')}. Speichern spielt sie auf alle aus.`
                             : 'Von keinem Panel benutzt, zum Beispiel als Vorlage.')
        : 'Noch keine Konfiguration.'}));
  }

  async function openConfig(id) {
    currentConfig = id;
    renderConfigs();
    ui.apply(await ws({type: 'smartbuttons/get_config', config_id: id}));
    ui.msg('');
  }

  // ── One password for the web UI and OTA of all panels ──
  async function renderPassword() {
    const input = el('input', {value: (await ws({type: 'smartbuttons/get_password'})).password,
                               style: 'font-family:monospace'});
    const set = el('button', {textContent: 'Passwort setzen'});
    set.onclick = () => act(ws({type: 'smartbuttons/set_password', password: input.value}),
                            r => `Passwort gesetzt, ${r.panels} verbundene Panels haben es schon.`)
      .catch(() => ui.msg('8 bis 32 Zeichen, ohne Leerzeichen und Umlaute.', 'err'));
    cards.password.replaceChildren(
      el('h2', {textContent: 'Passwort aller Panels'}),
      el('div', {className: 'inline'}, input, set),
      el('p', {className: 'hint', textContent:
        'Für Web-UI und OTA der Panels, Benutzer admin. Für OTA aus PlatformIO: SMARTBUTTONS_OTA_PASSWORD in .env.'}));
  }

  async function reload() {
    await refresh();
    if (!configs.some(c => c.id === currentConfig)) currentConfig = configs.length ? configs[0].id : null;
    renderPanels();
    renderConfigs();
    ui.lockEditor(!currentConfig);
    if (currentConfig) ui.apply(await ws({type: 'smartbuttons/get_config', config_id: currentConfig}));
  }

  return {
    hideName: true,
    hideRotation: true,
    hideTitle: true,
    saveLabel: 'Konfiguration speichern und ausspielen',
    entities(domains) {
      return Object.values(panel.hass.states)
        .filter(s => domains.includes(s.entity_id.split('.')[0]))
        .map(s => [s.entity_id, s.attributes.friendly_name || ''])
        .sort((a, b) => (a[1] || a[0]).localeCompare(b[1] || b[0]));
    },
    async start(editorUi) {
      ui = editorUi;
      cards.panels = el('div', {className: 'card'});
      cards.configs = el('div', {className: 'card'});
      cards.password = el('div', {className: 'card'});
      ui.slot.append(cards.panels, cards.configs);
      ui.slot.parentNode.append(cards.password);
      await reload();
      await renderPassword();
      // Status of the panels, while nobody types in that card.
      panel.poll = async () => {
        if (cards.panels.contains(panel.shadowRoot.activeElement)) return;
        try { panels = await ws({type: 'smartbuttons/panels'}); renderPanels(); } catch (e) { /* HA restarting */ }
      };
      panel.startPolling();
    },
    async save(config) {
      if (!currentConfig) throw new Error('keine Konfiguration gewählt');
      const r = await ws({type: 'smartbuttons/save_config', config_id: currentConfig, config});
      return `Gespeichert. ${r.pushed} Panels übernehmen es und starten neu` +
             (r.offline ? `, ${r.offline} offline bekommen es bei der nächsten Verbindung.` : '.');
    },
  };
}

